-- Preserve the named public donors and their unrelated loot.
DELIMITER //
BEGIN NOT ATOMIC
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    UPDATE lootdrop_entries SET chance=100 WHERE (lootdrop_id,item_id,chance) IN
       ((108794,85081,CAST(90 AS FLOAT)),(108840,85082,CAST(78.125 AS FLOAT)),
        (108855,85083,CAST(88.571 AS FLOAT)));
    IF ROW_COUNT() <> 3 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Tunare wood loot preimage mismatch';
    END IF;

    UPDATE npc_types SET loottable_id=304090415 WHERE id=378208 AND loottable_id=0;
    IF ROW_COUNT() <> 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Tunare Zorbig loot preimage mismatch';
    END IF;

    DELETE FROM loottable_entries WHERE loottable_id=92140 AND lootdrop_id=108852
       AND multiplier=1 AND droplimit=1 AND mindrop=0 AND probability=100;
    IF ROW_COUNT() <> 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Tunare Orgaf loot preimage mismatch';
    END IF;
END//
DELIMITER ;
COMMIT;
